/* @author MILO-GAO(高振銘)@2020 */ package page2020.view;public class Text extends Content<Text> {	private String text;	private String code;	private String icon;	private Object[] args;	public Text() {		super(ContentType.text);	}	public Text text(String text) {		this.text = text.trim();		this.code = null;		return this;	}	public Text code(String code) {		this.text = null;		this.code = code.trim();		return this;	}	public Text code(String code, Object... args) {		this.text = null;		this.code = code.trim();		this.args = args;		return this;	}	public Text icon(String icon) {		this.icon = "fas fa-fw fa-" + icon;		return this;	}	public Text reverse() {		this.icon = "far" + this.icon.substring(3);		return this;	}	public Text size(String size) {		switch (size) {		case "xs":		case "sm":		case "md":		case "lg":		case "2x":		case "3x":		case "4x":		case "5x":		case "6x":		case "7x":		case "8x":		case "9x":		case "10x":			this.icon += " fa-" + size;			break;		}		return this;	}	public Text spin() {		this.icon += " fa-spin";		return this;	}	public Text pulse() {		this.icon += " fa-pulse";		return this;	}	public Text fixed(boolean fixed) {		if (fixed) {			if (! this.icon.contains(" fa-fw")) {				this.icon += " fa-fw";			}		} else {			if (! this.icon.contains(" fa-fw")) {				this.icon = this.icon.replace(" fa-fw", "");			}		}		return this;	}	public Text border() {		this.icon += " fa-border";		return this;	}	public Text left() {		this.icon += " fa-pull-left";		return this;	}	public Text right() {		this.icon += " fa-pull-right";		return this;	}	public String getText() {		return text;	}	public void setText(String text) {		this.text = text;	}	public String getCode() {		return code;	}	public void setCode(String code) {		this.code = code;	}	public String getIcon() {		return icon;	}	public void setIcon(String icon) {		this.icon = icon;	}	public Object[] getArgs() {		return args;	}	public void setArgs(Object[] args) {		this.args = args;	}}